#!/usr/bin/env bash
# Sinh bởi tools/make-manifest.py. Chạy trong thư mục repo sau khi `gh auth login`.
# Mỗi tag một release; tên tag trùng thư mục trên máy chủ GameNative cũ, file gốc vào tag root.
# Release chưa có thì tạo kèm mọi file; có rồi thì chỉ tải lên file CHƯA có trên GitHub (so theo tên).
# Muốn thay một file đã có (đổi nội dung mà giữ tên — không nên): xoá asset trên GitHub rồi chạy lại.
set -euo pipefail
cd "$(dirname "$0")/.."

upload_tag() {
  local tag="$1"; shift
  local existing
  if existing=$(gh release view "$tag" --json assets --jq '.assets[].name' 2>/dev/null); then
    local missing=()
    for f in "$@"; do grep -qxF "$(basename "$f")" <<<"$existing" || missing+=("$f"); done
    if [ ${#missing[@]} -eq 0 ]; then echo "$tag: đủ $# file, không tải gì"; return; fi
    echo "$tag: tải lên ${#missing[@]} file còn thiếu"
    gh release upload "$tag" "${missing[@]}"
  else
    echo "$tag: tạo release với $# file"
    gh release create "$tag" "$@" --title "$tag" --notes "Gói của WOF Fly, nguồn gốc từng file xem files.json, kiểm bằng sha256sums.txt"
  fi
}

